mapper.select:
select jt.* from jw_team jt

     and team_name like concat('%', #{teamName}, '%')
     and user_name like concat('%', #{userName}, '%')
     and user_phone = #{userPhone}
     and addr = #{addr}
     and create_user_id = #{createUserId}

select jt.*, jmt.index_order, jsrr.singleCount, jsrr.qiCount, jsrr.singleSportCount, jsrr.qiSportCount from jw_team jt
left join jw_match_team jmt on jmt.team_id = jt.id
left join (
select jsr.team_id, jsr.match_id, count(case when jsr.sport_limit = '1' then 1 end) as singleCount,
sum(case when jsr.sport_limit = '1' then jsr.sportCount end) as singleSportCount,
count(case when (jsr.sport_limit = '3' or jsr.sport_limit = '2' or jsr.sport_limit = '4') then 1 end) as qiCount,
sum(case when (jsr.sport_limit = '3' or jsr.sport_limit = '2' or jsr.sport_limit = '4') then jsr.sportCount end) as qiSportCount
from (
select jr.*, count(jsrs.id) as sportCount from jw_sign_record jr
left join jw_sign_record_sport jsrs on jsrs.match_id = #{matchId} and jsrs.sign_record_id = jr.id group by jr.id ) jsr
where jsr.match_id = #{matchId} group by jsr.team_id ) jsrr on jsrr.team_id = jt.id

     and team_name like concat('%', #{teamName}, '%')
     and user_name like concat('%', #{userName}, '%')
     and user_phone = #{userPhone}
     and addr = #{addr}
     and create_user_id = #{createUserId}
     and jmt.match_id = #{matchId}
     and jmt.index_order = #{indexOrder}

order by jmt.index_order asc

mapper.update:
update jw_team
team_name = #{teamName}, user_name = #{userName}, user_phone = #{userPhone}, addr = #{addr}, create_time = #{createTime}, update_time = #{updateTime}, remark = #{remark}, create_user_id = #{createUserId}, match_id = #{matchId},
where id = #{id}
